const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines for a basic cart", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const cart = new Cart();
      cart.add(productA, 2); // original price 1000
      const result = await cart.checkout({ priceFetcher: fetcher });
      // refreshed price is 1500, subtotal = 1500*2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("propagates fetcher rejection", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "network error",
      );
    });

    it("throws RangeError for invalid fetched price", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("inventoryChecker", () => {
    it("passes when all items are available", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(4000);
      expect(checker.check).toHaveBeenCalledTimes(2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };
      const cart = new Cart();
      cart.add(productA, 5);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(0);
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2,
        }),
      };
      const cart = new Cart();
      cart.add(productA, 5);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "first denied" })
          .mockResolvedValueOnce({ available: false, reason: "second denied" }),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
        "first denied",
      );
      // Only first item checked since it fails
      expect(checker.check).toHaveBeenCalledTimes(1);
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax instead of sync calculator", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart(); // default NoTaxCalculator
      cart.add(productA, 1); // subtotal 1000, no discount
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // tax = floor(1000 * 0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(provider.getRate).toHaveBeenCalledWith("US");
    });

    it("async tax is computed on discounted subtotal", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 200 },
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, discounted = 800
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // tax = floor(800 * 0.1) = 80
      expect(result.totals.taxCents).toBe(80);
    });

    it("propagates async tax provider failure", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("throws for invalid rate from async provider", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("full checkout pipeline", () => {
    it("integrates priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 100 },
        shippingCalculator: { computeShippingCents: () => 300 },
      });
      cart.add(productA, 2);
      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });
      // refreshed price 500, qty 2 → subtotal 1000
      expect(result.totals.subtotalCents).toBe(1000);
      // discount 100, discounted = 900
      expect(result.totals.discountCents).toBe(100);
      // tax = floor(900 * 0.08) = 72
      expect(result.totals.taxCents).toBe(72);
      // shipping 300
      expect(result.totals.shippingCents).toBe(300);
      // total = 900 + 72 + 300 = 1272
      expect(result.totals.totalCents).toBe(1272);
    });
  });
});

